**Steps to reproduce or a small repository showing the problem:**
Create relations in embedded entity and look into database.
```ts
// File.ts
import { Column, Entity, PrimaryGeneratedColumn } from 'typeorm'

@Entity()
export class File {
  @PrimaryGeneratedColumn()
  id: number

  @Column()
  path: string

  @Column()
  filename: string

  @Column()
  mimetype: string
}

// Test.ts
import { Column, Entity, JoinColumn, OneToOne, PrimaryGeneratedColumn } from 'typeorm'
import { File } from './File'

class AdditionalInfoTest {
  @OneToOne(type => File, { onDelete: 'CASCADE' })
  @JoinColumn()
  logo?: File
}

@Entity()
export class Test {
  @PrimaryGeneratedColumn()
  id: number

  @Column(type => AdditionalInfoTest)
  info: AdditionalInfoTest = new AdditionalInfoTest()
}
```

